package dev.soundceiling.app;
import android.content.Context;import android.media.*;import android.os.*;
final class ToneController{enum Kind{SPEAKER_CHECK(-12f),CALIBRATION(-30f);final float peakDbfs;Kind(float p){peakDbfs=p;}}static final class Result{final Kind kind;final int playbackIndex,originalIndex;final AudioDeviceInfo routedDevice;final boolean volumeWasTemporary;Result(Kind k,int p,int o,AudioDeviceInfo r,boolean t){kind=k;playbackIndex=p;originalIndex=o;routedDevice=r;volumeWasTemporary=t;}}interface Listener{void onTick(Kind k,int remaining,int index);void onComplete(Result r);void onError(Kind k,String error);}private final AudioManager audio;private final Handler main=new Handler(Looper.getMainLooper());private AudioTrack track;private int original=-1;ToneController(Context c){audio=(AudioManager)c.getSystemService(Context.AUDIO_SERVICE);}synchronized void play(Kind kind,int maxPercent,Listener listener){cancel();original=audio.getStreamVolume(AudioManager.STREAM_MUSIC);int min=audio.getStreamMinVolume(AudioManager.STREAM_MUSIC),max=audio.getStreamMaxVolume(AudioManager.STREAM_MUSIC),playback=original;boolean temporary=false;if(playback==min&&max>min){int cap=Math.round(min+DbMath.clamp(maxPercent,0,100)/100f*(max-min));playback=Math.max(min+1,Math.min(cap,Math.round(min+.3f*(max-min))));audio.setStreamVolume(AudioManager.STREAM_MUSIC,playback,0);temporary=true;}final int p=playback,o=original;final boolean temp=temporary;new Thread(()->{AudioTrack local=null;try{short[] pcm=ToneSamples.sinePcm16(48000,3000,1000f,kind.peakDbfs,1);AudioAttributes attrs=new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION).setAllowedCapturePolicy(AudioAttributes.ALLOW_CAPTURE_BY_NONE).build();AudioFormat fmt=new AudioFormat.Builder().setEncoding(AudioFormat.ENCODING_PCM_16BIT).setSampleRate(48000).setChannelMask(AudioFormat.CHANNEL_OUT_MONO).build();local=new AudioTrack.Builder().setAudioAttributes(attrs).setAudioFormat(fmt).setTransferMode(AudioTrack.MODE_STATIC).setBufferSizeInBytes(pcm.length*2).build();synchronized(this){track=local;}local.write(pcm,0,pcm.length);local.play();for(int r=3;r>=1;r--){int tick=r;main.post(()->listener.onTick(kind,tick,p));Thread.sleep(1000);}AudioDeviceInfo routed=local.getRoutedDevice();restore();main.post(()->listener.onComplete(new Result(kind,p,o,routed,temp)));}catch(Exception e){restore();main.post(()->listener.onError(kind,e.getClass().getSimpleName()));}finally{if(local!=null)try{local.release();}catch(RuntimeException ignored){}}},"SoundCeilingTone").start();}synchronized void cancel(){AudioTrack t=track;track=null;if(t!=null)try{t.stop();}catch(RuntimeException ignored){}restore();}private synchronized void restore(){if(original<0)return;int r=original;original=-1;audio.setStreamVolume(AudioManager.STREAM_MUSIC,r,0);}}
